"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["65682"],{56778(e){e.exports=JSON.parse('{"id":"FIN-989","slug":"fat-tailed-distribution","term":"Fat-Tailed Distribution","also_known_as":[],"difficulty":"Intermediate","definition":"A fat-tailed distribution is a probability distribution in which extreme outcomes, far from the average, occur more often than they would under a normal distribution.","explanation":["The tails of a distribution are its far ends, representing extreme outcomes. In a normal distribution, the probability of extreme events falls off very quickly. In a fat-tailed distribution, extreme events are much more likely than the normal distribution predicts.","Financial returns are widely observed to be fat-tailed. For example, under a normal distribution, a daily fall in a stock market index of more than five standard deviations should happen so rarely that it might be expected only once in many thousands of years. In reality, such falls have happened several times within a few decades, including the 1987 crash and moves during the 2008 financial crisis.","Fat tails have important consequences for risk management. Models that assume normal distributions can seriously underestimate the probability of large losses, giving a false sense of security. Statisticians describe fat tails using measures such as kurtosis, which captures how heavy the tails are.","To address fat tails, risk managers use stress tests, historical worst-case scenarios, distributions that allow for more extreme outcomes and measures such as expected shortfall, which look at the size of losses in the tail rather than just the threshold."],"note":"","total":1500,"prev":{"slug":"fairness-opinion","term":"Fairness Opinion"},"next":{"slug":"favorable-variance","term":"Favorable Variance"}}')}}]);